```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:comment "An OWL ontology of securities, financial instruments, bonds, equities, derivatives and investment funds, modelled from an encyclopedic/glossary corpus." .

#################################################################
# TOP-LEVEL FINANCIAL INSTRUMENT CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties. IAS 32/39 define a financial instrument as any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "Instruments whose value is determined directly by the markets; includes securities and instruments such as loans and deposits where both borrower and lender must agree on a transfer." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative", "derivative instrument" ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf ( fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom owl:Thing ]
    )
  ] ;
  rdfs:comment "A contract whose value is derived from the performance of an underlier such as a commodity, financial instrument, index, currency, interest rate, or a specified event." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A non-negotiable cash instrument in which transfer requires agreement of both borrower and lender." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:FinancialAsset a owl:Class ;
  rdfs:comment "IAS 32: cash; an equity instrument of another entity; a contractual right to receive cash or another financial instrument; or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial instrument, or to exchange financial instruments under potentially unfavourable conditions." .

fis:EquityInstrument a owl:Class ;
  rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. NOTE: this accounting notion can diverge from the market classification fis:EquitySecurity -- e.g. a mandatorily redeemable preference share is market-labelled 'preferred equity' but is classified as a FinancialLiability under IAS 32 because the issuer cannot avoid delivering cash." .

fis:CompoundFinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "IAS 32: an instrument such as a convertible bond that must be split into a liability component and an equity component." .

fis:AmortizedCostFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "amortisedCost" ] ) ] .
fis:FVOCIFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVOCI" ] ) ] .
fis:FVTPLFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVTPL" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:AmortizedCostFinancialAsset fis:FVOCIFinancialAsset fis:FVTPLFinancialAsset ) ] .

#################################################################
# SECURITY
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument, fis:FinancialAsset ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset. Certificates may be bearer or registered; may be certificated or non-certificated (book-entry)." .

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "bearer" ] ) ] ;
  rdfs:comment "Completely negotiable; holding the certificate entitles the holder to rights under the security." .

fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "registered" ] ) ] ;
  rdfs:comment "Entitles holder to rights only if registered on a security register maintained by issuer or intermediary." .

owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

#################################################################
# MAIN SECURITY CATEGORIES: DEBT / EQUITY / HYBRID
#################################################################

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Issuer (debtor) owes the holder (creditor) a debt and is obliged to provide cash flow, typically repayment of principal plus interest." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "equity security", "stock", "capital stock", "share" ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; a residual ownership claim." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines some characteristics of both debt and equity securities." .

fis:ConvertibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A security that can be converted, at the election of the holder, into a specified number of shares of common stock." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) ] .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# ISSUERS AND HOLDERS
#################################################################

fis:Issuer a owl:Class ; rdfs:comment "The entity which is obligated on a security or other financial instrument." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "A local authority, subdivision, municipality, state, province or territory other than a sovereign government." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "An international organization such as the World Bank or IMF." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .

owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization fis:Corporation ) ] .

fis:Holder a owl:Class ; rdfs:comment "An entity entitled to rights under a security." .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ; rdfs:label "stockholder" .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder .

#################################################################
# BOND
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "The issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon) over time." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less. Certificates of deposit and commercial paper are classified as money market instruments and not bonds." .

owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a fixed term before withdrawal without penalty." .
fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually less than 270 days." .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term debt obligation of a national government, maturing in three to twelve months." .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:EurodollarDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

# --- Bond classified by nature of issuer ---

fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "sovereign bond", "treasury bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:comment "Medium or long term debt securities issued by sovereign governments or their agencies." .

fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:comment "Issued by state, local governments, or entities they create such as authorities and special districts." .

fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations during wartime." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and its taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment from a specified stream of future income rather than general taxing power; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments; generally a form of general obligation bond." .

owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:comment "A bond that matures in installments over a period of time." .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet (unlike asset-backed securities)." .

# --- Bond classified by coupon type ---

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] ;
  rdfs:comment "Interest payments remain constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] ;
  rdfs:comment "Variable coupon linked to a reference rate such as LIBOR, Euribor or SOFR." .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ] ) ] ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par value, with return realized at maturity." .

owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

# --- Bond classified by maturity feature ---

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:label "perpetuity" ;
  rdfs:comment "Has no maturity date; the issuer repays principal only at its discretion, if ever." .

# --- Embedded options on bonds ---

fis:EmbeddedOption a owl:Class ;
  rdfs:comment "Option-like features granted to the holder or issuer of a bond." .
fis:CallProvision a owl:Class ; rdfs:subClassOf fis:EmbeddedOption ;
  rdfs:comment "Gives the issuer the right to repay the bond before maturity." .
fis:PutProvision a owl:Class ; rdfs:subClassOf fis:EmbeddedOption ;
  rdfs:comment "Gives the holder the right to force early repayment." .
owl:AllDisjointClasses [ owl:members ( fis:CallProvision fis:PutProvision ) ] .

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallProvision ] ) ] .

fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "retractable bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutProvision ] ) ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

# --- Bond classified by ownership form ---

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity ;
  rdfs:comment "An official certificate issued without a named holder." .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity ;
  rdfs:comment "Ownership recorded by the issuer or transfer agent." .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "bookEntry" ] ) ] ;
  rdfs:comment "A bond that does not have a paper certificate." .

owl:AllDisjointClasses [ owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) ] .

# --- Bond classified by seniority ---

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] ;
  rdfs:comment "Lower priority than other bonds of the issuer in liquidation." .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

# --- Bond classified by credit rating ---

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "high grade bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "investmentGrade" ] ) ] .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "junk bond", "non-investment grade bond" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "nonInvestmentGrade" ] ) ] ;
  rdfs:comment "Rated below investment grade; investors expect higher yield to compensate for higher default risk." .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

# --- Convertible bonds ---

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:Bond, fis:ConvertibleSecurity, fis:HybridSecurity, fis:CompoundFinancialInstrument ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "Lets the holder exchange the bond into a number of shares of common stock of the issuing company." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .
fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs." .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond backed by a pool of assets such as loans, leases or receivables." .

fis:Mortgage a owl:Class .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:DebtObligation a owl:Class .

fis:MortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:comment "Structured ABS backed by debt obligations, often other asset-backed securities; sliced into tranches." .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Allocates cash flows from the underlying pool to holders on a pro rata basis." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "pay-through bond" .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "ordinary share" ;
  rdfs:comment "Typically carries voting rights and lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity, fis:HybridSecurity ;
  rdfs:label "preference share" ;
  rdfs:comment "Has priority over common stock for dividends and liquidation proceeds; generally considered a hybrid instrument." .

owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue "cumulative" ] ) ] ;
  rdfs:comment "Unpaid dividends accumulate and must be paid before common dividends resume." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue "noncumulative" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) ] .

fis:Dividend a owl:Class ; rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, unlike a bond coupon." .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
owl:AllDisjointClasses [ owl:members ( fis:CashDividend fis:StockDividend ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "An SEC-registered open-end investment company (or similar structure) pooling investor money." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Investors buy and sell shares on national securities exchanges at market prices that may differ from NAV, unlike mutual funds which transact only at NAV." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money but with fewer regulations and more flexible/risky strategies than mutual funds." .

owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolioComponent ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "income fund" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolioComponent ; owl:someValuesFrom fis:DebtSecurity ] ) ] .
fis:StockFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "equity fund" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasPortfolioComponent ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Blends equities and fixed income." .

owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under specified terms." .
owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:hasValue "exchange" ] ) ] .
fis:OverTheCounterDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:hasValue "OTC" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct, fis:OverTheCounterDerivative ;
  rdfs:comment "Non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ; rdfs:subClassOf fis:LockProduct, fis:ExchangeTradedDerivative ;
  rdfs:comment "Standardized contract written by a clearing house/exchange to buy or sell an asset on a future delivery date at a price agreed today." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future ) ] .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another over a notional principal amount." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .

fis:CreditDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "A contract that transfers credit risk from a protection buyer to a credit protection seller." .

fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
    [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:comment "Seller compensates buyer in the event of a loan default or other credit event on a reference entity." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Gives the holder the right, but not the obligation, to buy or sell an underlying asset at a strike price on or before a specified date." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "call" ] ) ] .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionType ; owl:hasValue "put" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "american" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "european" ] ) ] ;
  rdfs:comment "May only be exercised on the expiry date." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption ) ] .

fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .

fis:ExchangeTradedOption a owl:Class ; rdfs:subClassOf fis:Option, fis:ExchangeTradedDerivative .
fis:OverTheCounterOption a owl:Class ; rdfs:subClassOf fis:Option, fis:OverTheCounterDerivative .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedOption fis:OverTheCounterOption ) ] .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "A long-dated option, typically traded over the counter." .
fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:Warrant ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Issued by the company itself, allowing the holder to purchase a specific number of shares at a specified price within a specified time." .

fis:StockDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." .

fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option, fis:StockDerivative .
fis:StockFuture a owl:Class ; rdfs:subClassOf fis:Future, fis:StockDerivative .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer .
fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ; rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
